WITH src AS (SELECT * FROM store_sales WHERE (sale_date > '2025-01-29' AND store_id IN (1, 3, 5, 6)) OR revenue BETWEEN 3300 AND 3500), store_id_summary AS (SELECT store_id, MAX(sale_date) AS latest_sale_date, COUNT(*) AS num_store_sales FROM src GROUP BY store_id) SELECT * FROM store_id_summary WHERE num_store_sales > 7 ORDER BY latest_sale_date, num_store_sales, store_id LIMIT 3;
